package hu.synostream.android;
import android.content.*;import android.os.*;import android.app.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(AndroidJUnit4.class) public class Android0521Test {
 final Android050FlowTest f=new Android050FlowTest();java.util.function.Consumer<Intent> originalStarter;
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");originalStarter=f.app.scanServiceStarter;f.app.store.put("automatic_library_minutes","0");AppUpdates.get(f.context).automatic(false);AppUpdates.get(f.context).checked=true;f.instrumentation.runOnMainSync(()->{f.app.client=null;f.app.recovery.reset();f.app.checkNetwork();});}
 @After public void cleanup()throws Exception{f.instrumentation.runOnMainSync(()->{f.app.automaticForeground(false);f.app.cancelScan();f.app.scanServiceStarter=originalStarter;f.app.automaticCellular=()->false;f.app.store.put("automatic_library_minutes","5");f.app.store.put("automatic_library_mobile","false");});RecommendationsUi.stateReader=(p,k)->p.getString(k,"{}");RecommendationsUi.factory=k->(e,p)->new TmdbApi(k,null).get(e,p);f.cleanup();UiLocale.save(f.context,"hu");}
 void tick(){try{java.lang.reflect.Method m=SynoApp.class.getDeclaredMethod("checkAutomaticLibraries");m.setAccessible(true);m.invoke(f.app);}catch(Exception failure){throw new RuntimeException(failure);}}
 void waitFor(java.util.function.BooleanSupplier c)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(!c.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue("Operation did not finish",c.getAsBoolean());}
 @Test public void unknownFilesRequireOptInAndCheckboxResets()throws Exception{try(FakeNas nas=new FakeNas()){String root="/Movies/Unknown";nas.folders.add(root);nas.files.put(root+"/Movie.mkv",new byte[]{1});nas.files.put(root+"/notes.pdf",new byte[]{1});Library.Card card=new Library.Card(root+"/Movie.mkv","Unknown fixture",true);f.setup(nas,List.of(card));assertNotNull("Card must appear before opening details",f.device.wait(Until.findObject(By.desc(card.title)),10000));f.device.findObject(By.desc(card.title)).click();f.click("detail_delete");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/delete_unknown")),10000));assertFalse(f.device.findObject(By.res(f.pkg+":id/delete_unknown")).isChecked());assertTrue(f.device.hasObject(By.textContains("Ismeretlen fájlok")));f.device.findObject(By.res(f.pkg+":id/delete_unknown")).click();assertTrue(f.device.findObject(By.res(f.pkg+":id/delete_unknown")).isChecked());f.text("Mégse");f.click("detail_delete");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/delete_unknown")),10000));assertFalse(f.device.findObject(By.res(f.pkg+":id/delete_unknown")).isChecked());assertEquals(0,nas.mediaDeletes);f.text("Mégse");}}
 @Test public void missingPhysicalPathsShowEnglishErrorAndNeverDelete()throws Exception{try(FakeNas nas=new FakeNas()){UiLocale.save(f.context,"en");nas.omitRealPath=true;Library.Card card=new Library.Card("/Movies/Demo.Movie.2020.mkv","Physical fixture",true);f.setup(nas,List.of(card));assertNotNull("Card must appear before opening details",f.device.wait(Until.findObject(By.desc(card.title)),10000));f.device.findObject(By.desc(card.title)).click();f.click("detail_delete");assertTrue(f.device.wait(Until.hasObject(By.textContains("physical path")),10000));assertEquals(0,nas.mediaDeletes);}}
 @Test public void automaticMobileGateNoServiceAndBackgroundCancellation()throws Exception{try(FakeNas nas=new FakeNas()){f.setup(nas,List.of());nas.folders.add("/Movies/Slow");nas.files.put("/Movies/Slow/Fixture.mkv",new byte[]{1});nas.gatedFolder="/Movies/Slow";AtomicInteger services=new AtomicInteger();try{f.instrumentation.runOnMainSync(()->{f.app.store.put("automatic_library_minutes","5");f.app.store.put("automatic_library_mobile","false");f.app.automaticCellular=()->true;f.app.scanServiceStarter=i->services.incrementAndGet();f.app.automaticLibraries.reset();f.app.automaticForeground(true);tick();});Thread.sleep(1200);assertFalse(f.app.scanRunning);assertEquals(0,services.get());f.instrumentation.runOnMainSync(()->{f.app.store.put("automatic_library_mobile","true");tick();});assertTrue(nas.folderEntered.await(10,TimeUnit.SECONDS));assertTrue(f.app.automaticScan);assertEquals(0,services.get());for(android.service.notification.StatusBarNotification n:f.context.getSystemService(NotificationManager.class).getActiveNotifications())assertNotEquals(42,n.getId());f.instrumentation.runOnMainSync(()->f.app.automaticForeground(false));assertFalse(f.app.scanRunning);assertFalse(f.app.automaticScan);assertFalse(f.app.store.get("scan_pending","").isEmpty());}finally{nas.releaseFolder.countDown();}}}
 @Test public void offBlocksAutomaticButForceStillUsesManualServiceLauncher()throws Exception{try(FakeNas nas=new FakeNas()){f.setup(nas,List.of());AtomicInteger services=new AtomicInteger();f.instrumentation.runOnMainSync(()->{f.app.store.put("automatic_library_minutes","0");f.app.automaticCellular=()->false;f.app.scanServiceStarter=i->services.incrementAndGet();f.app.automaticLibraries.reset();f.app.automaticForeground(true);tick();});Thread.sleep(1200);assertFalse(f.app.scanRunning);assertEquals(0,services.get());f.instrumentation.runOnMainSync(()->f.app.scan(f.app.selected(),true));assertEquals(1,services.get());}}
 @Test public void recommendationStateLoadsOffMainAndShowsLoadingPanel()throws Exception{try(FakeNas nas=new FakeNas()){Library.Card card=new Library.Card("/Movies/Demo.Movie.2020.mkv","Cache fixture",true);card.id=10;f.setup(nas,List.of(card));f.app.store.secret("tmdb_key","fixture-key");f.context.getSharedPreferences("recommendations",0).edit().putBoolean("prefer_hu",false).commit();RecommendationsUi.factory=k->(e,p)->new JSONObject().put("results",new JSONArray());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicBoolean offMain=new AtomicBoolean();RecommendationsUi.stateReader=(prefs,key)->{offMain.set(Looper.myLooper()!=Looper.getMainLooper());entered.countDown();try{release.await(10,TimeUnit.SECONDS);}catch(InterruptedException stop){Thread.currentThread().interrupt();}return prefs.getString(key,"{}");};try{f.click("tab_recommendations");assertTrue(entered.await(5,TimeUnit.SECONDS));assertTrue(f.device.hasObject(By.text("Betöltés…")));CountDownLatch ui=new CountDownLatch(1);f.app.main.post(ui::countDown);assertTrue(ui.await(2,TimeUnit.SECONDS));release.countDown();waitFor(()->f.activity().recommendationsUi.engine!=null&&!f.activity().recommendationsUi.restoring);assertTrue(offMain.get());}finally{release.countDown();}}}
 @Test public void refreshOptionsAreSavedInExistingStore()throws Exception{try(FakeNas nas=new FakeNas()){f.setup(nas,List.of());MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->{f.app.page="settings";a.invalidatePage();});new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text("Automatikus médiatár-frissítés"));f.text("Automatikus médiatár-frissítés");f.text("15 perc");waitFor(()->"15".equals(f.app.store.get("automatic_library_minutes","")));assertEquals("15",f.app.store.get("automatic_library_minutes",""));new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text("Mobilhálózaton is"));assertTrue(f.device.wait(Until.hasObject(By.text("Mobilhálózaton is")),5000));f.text("Mobilhálózaton is");waitFor(()->"true".equals(f.app.store.get("automatic_library_mobile","")));assertEquals("true",f.app.store.get("automatic_library_mobile",""));}}
}
